    '        )\n'
    '\n'
    '    print("=" * 80)\n'
    '\n'
    '    print(f"Total de productos: {len(productos)}")\n'
    '\n'
    '\n'
    'def mostrar_rendimiento(resultado):\n'
    '\n'
    '    print("\\nRENDIMIENTO DEL ORDENAMIENTO")\n'
    '\n'
    '    print("-" * 45)\n'
    '\n'
    '    print(\n'
    '        f"Algoritmo: {resultado[\'algoritmo\']}"\n'
    '    )\n'
    '\n'
    '    print(\n'
    '        f"Productos: {resultado[\'cantidad\']}"\n'
    '    )\n'
    '\n'
    '    print(\n'
    '        f"Tiempo: {resultado[\'tiempo\']:.8f} segundos"\n'
