    '\n'
    '    print(\n'
    '        f"Complejidad: {resultado[\'complejidad\']}"\n'
    '    )\n'
    '\n'
    '    print("-" * 45)\n'
    '\n'
    '\n'
    '# ==========================================\n'
    '# GENERACION DE DATOS DE PRUEBA\n'
    '# ==========================================\n'
    '\n'
    'def generar_productos_prueba(cantidad):\n'
    '\n'
    '    if not isinstance(cantidad, int):\n'
    '\n'
    '        raise ValueError("La cantidad debe ser entera.")\n'
    '\n'
    '    if not 1 <= cantidad <= 100000:\n'
    '\n'
    '        raise ValueError(\n'
    '            "La prueba permite entre 1 y 100000 productos."\n'
    '        )\n'
    '\n'
    '    generador = Random(42)\n'
    '\n'
    '    productos = []\n'
    '\n'
    '    for i in range(cantidad):\n'
    '\n'
    '        producto = {\n'
    '            "codigo": f"P{i + 1:06d}",\n'
    '            "nombre": f"Producto {i + 1}",\n'
    '            "categoria": "Prueba",\n'
    '            "precio_centavos": generador.randint(\n'
    '                1, 1000000\n'
    '            ),\n'
    '            "stock": generador.randint(0, 100000),\n'
    '            "activo": 1\n'
    '        }\n'
    '\n'
    '        productos.append(producto)\n'
    '\n'
    '    return productos\n'
    '\n'
    '\n'
    '# ==========================================\n'
    '# COMPARACION DE ALGORITMOS\n'
    '# ==========================================\n'
    '\n'
    'def comparar_algoritmos():\n'
    '\n'
    '    cantidades = [\n'
    '        100,\n'
    '        500,\n'
    '        1000,\n'
    '        10000,\n'
    '        100000\n'
    '    ]\n'
    '\n'
    '    print("\\n" + "=" * 70)\n'
    '\n'
    '    print("PRUEBA DE RENDIMIENTO DE ALGORITMOS")\n'
    '\n'
    '    print("=" * 70)\n'
    '\n'
    '    for cantidad in cantidades:\n'
