    '        )\n'
    '\n'
    '        tiempo_merge = perf_counter() - inicio\n'
    '\n'
    '        print(\n'
    '            f"Merge Sort: "\n'
    '            f"{tiempo_merge:.8f} segundos"\n'
    '        )\n'
    '\n'
    '        print(\n'
    '            "Resultado correcto:",\n'
    '            resultado_merge == esperado\n'
    '        )\n'
    '\n'
    '        resultado = ordenamiento_adaptativo(\n'
    '            productos,\n'
    '            "precio_centavos"\n'
    '        )\n'
    '\n'
    '        print(\n'
    '            f"Modo adaptativo: {resultado[\'algoritmo\']}"\n'
    '        )\n'
    '\n'
    '        print(\n'
    '            "Resultado adaptativo correcto:",\n'
    '            resultado["productos"] == esperado\n'
    '        )\n'
    '\n'
    '    print("\\nPruebas finalizadas.")\n'
    '\n'
    '\n'
    '# ==========================================\n'
    '# MENU DE CONSOLA\n'
    '# ==========================================\n'
    '\n'
    'def menu_algoritmos():\n'
    '\n'
    '    while True:\n'
    '\n'
    '        print("\\n" + "=" * 45)\n'
    '\n'
    '        print("TIENDAS MI CHOLO - ALGORITMOS")\n'
    '\n'
    '        print("=" * 45)\n'
    '\n'
