# ===== COMPONENTE: seguridad.py =====
FUENTES['seguridad'] = (
    'import repositorios as repo\n'
    'import sqlite3\n'
    'import logging\n'
    'from datetime import datetime\n'
    'from pathlib import Path\n'
    'from contextlib import closing\n'
    'from base_datos import conectar, inicializar_base_datos, CARPETA_BACKUPS, RUTA_DB\n'
    '\n'
    '\n'
    'def registrar_error(error):\n'
    '    CARPETA_BACKUPS.mkdir(parents=True, exist_ok=True)\n'
    "    logger = logging.getLogger('mi_cholo.seguridad')\n"
    '    logger.setLevel(logging.ERROR)\n'
    '    logger.propagate = False\n'
    '    if not logger.handlers:\n'
    "        handler = logging.FileHandler(CARPETA_BACKUPS / 'errores.log', encoding='utf-8')\n"
    "        handler.setFormatter(logging.Formatter('%(asctime)s | %(levelname)s | %(message)s'))\n"
    '        logger.addHandler(handler)\n'
    "    logger.error('%s', error)\n"
    '\n'
    '\n'
    'def verificar_conexion(conexion):\n'
    '    resultados = repo.consultar_integridad(conexion).fetchall()\n'
    "    if [fila[0] for fila in resultados] != ['ok']:\n"
    "        raise ValueError('La base de datos presenta problemas de integridad.')\n"
    '    if repo.consultar_claves_foraneas(conexion).fetchone() is not None:\n'
    "        raise ValueError('Existen relaciones invalidas entre registros.')\n"
    "    tablas = {'productos', 'ventas', 'detalle_venta', 'usuarios', 'auditoria'}\n"
    '    existentes = {fila[0] for fila in repo.consultar_tablas(conexion)}\n'
    '    if not tablas.issubset(existentes):\n'
    "        raise ValueError('La copia no contiene las tablas requeridas.')\n"
    '    return True\n'
    '\n'
    '\n'
    'def verificar_integridad():\n'
    '    with closing(conectar()) as conexion:\n'
    '        return verificar_conexion(conexion)\n'
    '\n'
    '\n'
    'def abrir_copia(ruta):\n'
    "    return sqlite3.connect(Path(ruta).resolve().as_uri() + '?mode=ro', uri=True, timeout=10)\n"
    '\n'
    '\n'
    "def crear_backup(tipo='manual'):\n"
    "    if tipo not in ('manual', 'automatico', 'preventivo'):\n"
    "        raise ValueError('Tipo de respaldo invalido.')\n"
    '    CARPETA_BACKUPS.mkdir(parents=True, exist_ok=True)\n'
    "    fecha = datetime.now().strftime('%Y%m%d_%H%M%S_%f')\n"
    "    ruta = CARPETA_BACKUPS / f'{tipo}_{fecha}.db'\n"
    "    temporal = ruta.with_suffix('.tmp')\n"
    '    try:\n'
    '        with closing(conectar()) as origen, closing(sqlite3.connect(temporal)) as destino:\n'
    '            origen.backup(destino)\n'
    '            verificar_conexion(destino)\n'
    '        temporal.replace(ruta)\n'
    '        return ruta\n'
    '    except (ValueError, sqlite3.Error, OSError):\n'
    '        temporal.unlink(missing_ok=True)\n'
    '        raise\n'
    '\n'
    '\n'
    'def listar_backups():\n'
    '    CARPETA_BACKUPS.mkdir(parents=True, exist_ok=True)\n'
    "    return sorted(CARPETA_BACKUPS.glob('*.db'), key=lambda ruta: ruta.stat().st_mtime, reverse=True)\n"
    '\n'
    '\n'
    'def backup_automatico():\n'
    "    hoy = datetime.now().strftime('%Y%m%d')\n"
    '    for ruta in listar_backups():\n'
    "        if ruta.name.startswith(f'automatico_{hoy}_'):\n"
    '            try:\n'
    '                with closing(abrir_copia(ruta)) as conexion:\n'
    '                    verificar_conexion(conexion)\n'
    '                return ruta\n'
    '            except (ValueError, sqlite3.Error, OSError) as error:\n'
    '                registrar_error(error)\n'
    "    return crear_backup('automatico')\n"
    '\n'
    '\n'
    'def restaurar_backup(ruta, confirmacion):\n'
    "    if confirmacion != 'RESTAURAR':\n"
    "        raise ValueError('Restauracion cancelada.')\n"
    '    ruta = Path(ruta).resolve()\n'
    "    if ruta.parent != CARPETA_BACKUPS.resolve() or ruta.suffix != '.db' or not ruta.is_file() or ruta == RUTA_DB.resolve():\n"
    "        raise ValueError('Seleccione una copia valida de la carpeta backups.')\n"
    '    # Ejecutar exclusivamente con las otras instancias del sistema cerradas.\n'
    '    with closing(abrir_copia(ruta)) as origen:\n'
    '        verificar_conexion(origen)\n'
    "        preventivo = crear_backup('preventivo')\n"
    '        with closing(conectar()) as destino:\n'
    '            origen.backup(destino)\n'
    '            verificar_conexion(destino)\n'
    '    return preventivo\n'
    '\n'
    '\n'
    'def menu_seguridad():\n'
    '    while True:\n'
    "        print('\\n=== TIENDAS MI CHOLO - SEGURIDAD ===')\n"
    "        print('1. Crear copia manual\\n2. Listar copias\\n3. Verificar integridad\\n4. Crear copia diaria\\n5. Restaurar copia\\n0. Regresar')\n"
    '        try:\n'
    "            opcion = input('Seleccione una opcion: ').strip()\n"
    "            if opcion == '0':\n"
    '                break\n'
    "            elif opcion == '1':\n"
    "                print('[OK]', crear_backup())\n"
    "            elif opcion == '2':\n"
    '                for i, ruta in enumerate(listar_backups(), 1):\n'
    '                    print(i, ruta.name)\n'
    "            elif opcion == '3':\n"
    '                verificar_integridad()\n'
    "                print('[OK] Base de datos integra.')\n"
    "            elif opcion == '4':\n"
    "                print('[OK]', backup_automatico())\n"
    "            elif opcion == '5':\n"
    '                copias = listar_backups()\n'
    '                if not copias:\n'
    "                    print('No existen copias.')\n"
    '                    continue\n'
    '                for i, ruta in enumerate(copias, 1):\n'
    '                    print(i, ruta.name)\n'
    "                numero = input('Numero de copia: ').strip()\n"
    '                if not numero.isascii() or not numero.isdigit() or len(numero) > 8 or not 1 <= int(numero) <= len(copias):\n'
    "                    raise ValueError('Numero invalido.')\n"
    "                print('ADVERTENCIA: cierre todas las otras instancias del sistema. Se reemplazaran los datos actuales.')\n"
    "                confirmacion = input('Escriba RESTAURAR para confirmar: ')\n"
    "                print('[OK] Respaldo previo:', restaurar_backup(copias[int(numero)-1], confirmacion))\n"
    '            else:\n'
    "                print('Opcion incorrecta.')\n"
    '        except (KeyboardInterrupt, EOFError):\n'
    '            break\n'
    '        except (ValueError, sqlite3.Error, OSError) as error:\n'
    "            print('Error:', error)\n"
    '            try:\n'
    '                registrar_error(error)\n'
    '            except OSError:\n'
    "                print('No se pudo escribir el registro de errores.')\n"
    '\n'
    '\n'
    "if __name__ == '__main__':\n"
    '    inicializar_base_datos()\n'
    '    menu_seguridad()\n'
)

