    '    return dict(fila)\n'
    '\n'
    '\n'
    'def verificar_permiso(id_usuario, roles=ROLES):\n'
    '    with closing(conectar()) as conexion:\n'
    '        return _autorizar(conexion, id_usuario, roles)\n'
    '\n'
    '\n'
    'def crear_usuario(id_admin, usuario, nombre, password, rol):\n'
    '    with closing(conectar()) as conexion, conexion:\n'
    '        repo.iniciar_transaccion(conexion)\n'
    "        _autorizar(conexion, id_admin, ('Administrador',))\n"
    '        return _insertar(conexion, usuario, nombre, password, rol)\n'
    '\n'
    '\n'
    'def listar_usuarios(id_admin):\n'
    '    with closing(conectar()) as conexion:\n'
