# Cargador de componentes incluidos en este mismo archivo.
import builtins

class Cargador(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    def find_spec(self, fullname, path=None, target=None):
        if fullname in FUENTES:
            return importlib.util.spec_from_loader(fullname, self, origin=builtins.str(Path(__file__).resolve()))
    def create_module(self, spec):
        return None
    def get_code(self, fullname):
        return builtins.compile(FUENTES[fullname], builtins.str(Path(__file__).resolve()) + ':' + fullname, 'exec')
    def get_source(self, fullname):
        return FUENTES[fullname]
    def get_filename(self, fullname):
        return builtins.str(Path(__file__).resolve())
    def exec_module(self, module):
        module.__file__ = builtins.str(Path(__file__).resolve())
        builtins.exec(self.get_code(module.__name__), module.__dict__)

def iniciar():
    parser = argparse.ArgumentParser(description='Tiendas Mi Cholo - archivo único')
    grupo = parser.add_mutually_exclusive_group()
    grupo.add_argument('--consola', action='store_true')
    grupo.add_argument('--web', action='store_true')
    grupo.add_argument('--pruebas', action='store_true')
    args = parser.parse_args()
    sys.meta_path.insert(0, Cargador())
    sys.argv = [sys.argv[0]]
    destino = 'pruebas' if args.pruebas else 'web' if args.web else 'consola' if args.consola else 'interfaz'
    if args.web:
        web = importlib.import_module("web")
        from jinja2 import DictLoader
        web.app.jinja_loader = DictLoader({'web.html': HTML_WEB})
        web.app.view_functions['static'] = lambda filename: web.app.response_class(CSS_WEB, mimetype='text/css') if filename == 'cholo.css' else ('No encontrado', 404)
        web.db.inicializar_base_datos()
        if web.u.necesita_administrador():
            web.u.crear_primer_administrador(builtins.input('Usuario administrador: '), builtins.input('Nombre: '), web.getpass.getpass('Contrasena: '))
        from waitress import serve
        builtins.print('Abrir http://127.0.0.1:8080')
        serve(web.app, host='127.0.0.1', port=8080)
    else:
        runpy.run_module(destino, run_name='__main__', alter_sys=True)

if __name__ == '__main__':
    iniciar()
